#include <stdio.h>
#include <stdarg.h>

int fish_total(int count, ...) {
    va_list list;
    va_start(list, count);
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += va_arg(list, int);
    }
    va_end(list);
    return sum;
}

int main(void) {
    printf("三只猫的：%d\n", fish_total(3, {a}, {b}, {c}));
    printf("五只猫的：%d\n", fish_total(5, {a}, {b}, {c}, {b}, {a}));
    return 0;
}
